func init() {
	for bookIndex := range wordbooks {
		for wordIndex := range wordbooks[bookIndex].Words {
			word := &wordbooks[bookIndex].Words[wordIndex]
			details, ok := studyCards[word.Term]
			if !ok {
				continue
			}
			word.Phonetic = details.phonetic
			word.PartOfSpeech = details.partOfSpeech
			word.Category = details.category
			word.Definition = details.definition
			word.Examples = []string{details.example}
		}
	}
}
